INPUT.ONCLICK:
exec spmpKontrolaOdabranogPartneraNG @action = 0, @partneriid = @@partneriid
					#if @@otkupugovorid is null or @@otkupugovorid = 0 begin 
						exec spRaiserror 69001, 'Nije odabran kooperantski ugovor! Molimo, odaberite ugovor!'
					end else begin 
						exec spMPInsertGlaIdetNG @action = 1, @operateriid = @@operateriid, @sifradok = '106', @status = 1, @vrstadokid = @@vrstadokid, 
						@datumdok = @@datumdok, @trgovinaid = @@trgovinaid, @osobeid = @@osobeid, @partneriid = @@partneriid, 
						@lokacijeid = @@lokacijeid, @rabat = @@rabat, @napomena = '@@napomena', @datumvalute = @@dat2isporuke, 
						@ucesce = @@ucesce, @ProNacinIsporukeId = @@ProNacinIsporukeId, @otkupugovorid = @@otkupugovorid, @OsobeParId = @@OsobeParId,
						@KomercijalistId = @@KomercijalistId end#OK#:UPDATE_FORM

exec spmpKontrolaOdabranogPartneraNG @action = 0, @partneriid = @@partneriid
					#if @@otkupugovorid is null or @@otkupugovorid = 0 begin 
						exec spRaiserror 69001, 'Nije odabran kooperantski ugovor ! Dokument se ne može spremiti !'
					end else begin 
						exec spMPInsertGlaIdetNG @action = 2, @id = @@id, @operateriid = @@operateriid, @sifradok = '106', @datumdok = @@datumdok, 
						@napomena = '@@napomena', @osobeid = @@osobeid, @rabat = @@rabat, @ucesce = @@ucesce, @datumvalute = @@dat2isporuke, 
						@partneriid = @@partneriid, @lokacijeid = @@lokacijeid, @status = 1, @ProNacinIsporukeId = @@ProNacinIsporukeId, 
						@otkupugovorid = @@otkupugovorid, @OsobeParId = @@OsobeParId, @KomercijalistId = @@KomercijalistId end#Ok
